// frontend/src/App.js
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import { WSProvider, useWS } from './context/WSContext';
import { ThemeProvider, useTheme, THEMES } from './context/ThemeContext';
import { ToastContainer } from './components/UI';
import Sidebar from './components/Sidebar';

import { LoginPage, RegisterPage } from './pages/Auth';
import Dashboard from './pages/Dashboard';
import Targets from './pages/Targets';
import Jobs from './pages/Jobs';
import Destinations from './pages/Destinations';
import SFTPExplorer from './pages/SFTPExplorer';
import { HistoryPage, LiveLogsPage } from './pages/History';
import { StoragePage, PrimaryDCPage, SecondaryDCPage, SettingsPage, UsersPage } from './pages/Storage';

import './index.css';

function RequireAuth({ children }) {
  const { isAuthenticated } = useAuth();
  return isAuthenticated ? children : <Navigate to="/login" replace/>;
}

function ThemeSwitcher() {
  const { theme, setTheme } = useTheme();
  return (
    <div style={{ display:'flex', gap:4, padding:'0 6px' }}>
      {Object.entries(THEMES).map(([key, t]) => (
        <button key={key} onClick={() => setTheme(key)} title={t.label}
          style={{
            display:'flex', alignItems:'center', gap:4, padding:'5px 9px',
            borderRadius:6, border: theme===key ? '1px solid var(--bv-blue,#58a6ff)' : '1px solid var(--bv-bd,#30363d)',
            background: theme===key ? 'rgba(88,166,255,0.12)' : 'transparent',
            color: theme===key ? 'var(--bv-blue,#58a6ff)' : 'var(--bv-txt2,#8b949e)',
            fontSize:11, cursor:'pointer', fontFamily:'inherit', fontWeight: theme===key?500:400,
          }}>
          <i className={`ti ti-${t.icon}`} style={{fontSize:13}}/>
          {t.label}
        </button>
      ))}
    </div>
  );
}

function Layout() {
  const { connected } = useWS();
  const { theme } = useTheme();

  const bg  = THEMES[theme]?.vars['--bv-bg']  || '#0d1117';
  const bg2 = THEMES[theme]?.vars['--bv-bg2'] || '#161b22';
  const bd  = THEMES[theme]?.vars['--bv-bd']  || '#30363d';
  const txt = THEMES[theme]?.vars['--bv-txt']  || '#e6edf3';

  return (
    <div style={{ display:'flex', height:'100vh', overflow:'hidden', background:bg, color:txt }}>
      <Sidebar wsConnected={connected}/>
      <div style={{ flex:1, overflow:'hidden', display:'flex', flexDirection:'column', background:bg }}>
        {/* Top bar with theme switcher */}
        <div style={{ borderBottom:`1px solid ${bd}`, background:bg2, padding:'6px 16px', display:'flex', alignItems:'center', justifyContent:'flex-end', flexShrink:0 }}>
          <ThemeSwitcher/>
        </div>
        <div style={{ flex:1, overflow:'hidden', display:'flex' }}>
          <Routes>
            <Route path="/dashboard"    element={<Dashboard/>}/>
            <Route path="/targets"      element={<Targets/>}/>
            <Route path="/jobs"         element={<Jobs/>}/>
            <Route path="/destinations" element={<Destinations/>}/>
            <Route path="/primary-dc"   element={<PrimaryDCPage/>}/>
            <Route path="/secondary"    element={<SecondaryDCPage/>}/>
            <Route path="/remote"       element={<SFTPExplorer/>}/>
            <Route path="/aws-s3"       element={<StoragePage/>}/>
            <Route path="/history"      element={<HistoryPage/>}/>
            <Route path="/live-logs"    element={<LiveLogsPage/>}/>
            <Route path="/users"        element={<UsersPage/>}/>
            <Route path="/settings"     element={<SettingsPage/>}/>
            <Route path="*"             element={<Navigate to="/dashboard" replace/>}/>
          </Routes>
        </div>
      </div>
    </div>
  );
}

function AuthenticatedApp() {
  return (
    <WSProvider>
      <Layout/>
    </WSProvider>
  );
}

export default function App() {
  return (
    <ThemeProvider>
      <AuthProvider>
        <BrowserRouter>
          <Routes>
            <Route path="/login"    element={<LoginPage/>}/>
            <Route path="/register" element={<RegisterPage/>}/>
            <Route path="/*" element={
              <RequireAuth>
                <AuthenticatedApp/>
              </RequireAuth>
            }/>
          </Routes>
          <ToastContainer/>
        </BrowserRouter>
      </AuthProvider>
    </ThemeProvider>
  );
}
